python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); 
for i in range(1, 4): 
  for j in range(i+1, 5): 
    c0 = train[train['target']==0][f'x{i:02}'].cov(train[train['target']==0][f'x{j:02}']); 
    c1 = train[train['target']==1][f'x{i:02}'].cov(train[train['target']==1][f'x{j:02}']); 
    print(f'x{i:02},x{j:02}: {c0:.4f} vs {c1:.4f}')"
